<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/seafort/app/bootstrap.php';
require_once dirname(__DIR__,2).'/seafort/app/documents.php';
sf_admin_session();if(empty($_SESSION['authenticated'])){header('Location: /admin/',true,303);exit;}
$base='/admin/documents.php';$error='';$notice='';$settings=sf_documents_settings();
$id=is_string($_GET['edit']??null)?$_GET['edit']:'';$isNew=isset($_GET['new']);$tab=($_GET['tab']??'')==='settings'?'settings':'list';
$item=$id!==''?sf_document_find($id):null;
if($id!==''&&!$item)$error='Belge bulunamadı.';
if(isset($_GET['download'])){
    $download=sf_document_find(is_string($_GET['download'])?$_GET['download']:'');
    if(!$download){http_response_code(404);exit('Belge bulunamadı.');}
    sf_document_send($download);
}
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    $action='';
    try{
        sf_require_csrf();$action=is_string($_POST['action']??null)?$_POST['action']:'';
        if($action==='logout'){sf_logout();header('Location: /admin/',true,303);exit;}
        if($action==='save_settings'){
            sf_documents_save_settings($_POST,is_string($_POST['revision']??null)?$_POST['revision']:'');
            $_SESSION['document_notice']='Belge merkezi sayfa metinleri kaydedildi.';header('Location: '.$base.'?tab=settings',true,303);exit;
        }
        if($action==='save'){
            $id=is_string($_POST['id']??null)?$_POST['id']:'';$isNew=$id==='';
            $saved=sf_document_save($_POST,isset($_FILES['pdf'])&&is_array($_FILES['pdf'])?$_FILES['pdf']:null,$id,is_string($_POST['revision']??null)?$_POST['revision']:'');
            $_SESSION['document_notice']=($_POST['status']??'')==='published'?'Belge yayımlandı. Belge merkezinde görüntülenebilir.':'Belge taslak kaydedildi; ziyaretçilere kapalı.';
            header('Location: '.$base.'?edit='.$saved,true,303);exit;
        }
        if($action==='delete'){
            if(($_POST['confirm_delete']??'')!=='1')throw new InvalidArgumentException('Kalıcı silme onayını işaretleyin.');
            sf_document_delete(is_string($_POST['id']??null)?$_POST['id']:'');
            $_SESSION['document_notice']='Belge ve PDF dosyası silindi.';header('Location: '.$base,true,303);exit;
        }
        throw new InvalidArgumentException('İşlem tanınmadı.');
    }catch(InvalidArgumentException $exception){$error=$exception->getMessage();}
    catch(Throwable){$error='İşlem tamamlanamadı. Mevcut belgeler korunuyor; dosya izinlerini kontrol edin.';}
    if($action==='save'){
        $old=$id!==''?sf_document_find($id):[];
        $item=$old?:[];
        foreach(['title','category','language','description','version','document_date','order','status'] as $key)if(is_string($_POST[$key]??null))$item[$key]=$_POST[$key];
        $item['permission_approved']=($_POST['permission_approved']??'')==='1';
    }
}
if(isset($_SESSION['document_notice'])){$notice=(string)$_SESSION['document_notice'];unset($_SESSION['document_notice']);}
if($isNew)$item=array_replace(['id'=>'','title'=>'','category'=>'brochure','language'=>'en','description'=>'','version'=>'','document_date'=>'','order'=>10,'status'=>'draft','permission_approved'=>false,'file'=>'','bytes'=>0,'updated_at'=>''],$item??[]);
$settings=sf_documents_settings();$items=sf_documents_list(false);
$counts=['all'=>count($items),'published'=>0,'draft'=>0];foreach($items as $entry)$counts[$entry['status']==='published'?'published':'draft']++;
$categoryLabels=['brochure'=>'Broşür','certificate'=>'Sertifika','wps'=>'Kaynak / WPS belgesi','sustainability'=>'Sürdürülebilirlik raporu'];
$filter=is_string($_GET['category']??null)&&isset($categoryLabels[$_GET['category']])?$_GET['category']:'';
function sf_doc_admin_input(string $name,string $label,mixed $value,string $type='text',int $max=180,bool $required=false):void
{
    echo '<div class="document-field"><label for="field-'.sf_escape($name).'">'.sf_escape($label).'</label><input name="'.sf_escape($name).'" id="field-'.sf_escape($name).'" type="'.sf_escape($type).'" maxlength="'.$max.'" value="'.sf_escape($value).'"'.($required?' required':'').'></div>';
}
