<div class="admin-main"><header class="topbar"><p>SEAFORT / Belge merkezi</p><a href="/documents/" target="_blank" rel="noopener">Sayfayı görüntüle</a></header><main class="workspace document-workspace" id="content"><div class="page-heading"><div><p class="eyebrow">KURUMSAL DOSYALAR</p><h1>Belge merkezi</h1><p class="muted">Broşür, rapor ve teknik belgeleri gerçek dosyalarıyla yönetin.</p></div><?php if(!$item&&$tab==='list'):?><a class="button" href="<?=$base?>?new=1">Belge ekle</a><?php endif;?></div>
<?php if($notice!==''):?><div class="alert alert-success" role="status"><?=sf_escape($notice)?></div><?php endif;?><?php if($error!==''):?><div class="alert alert-error" role="alert"><?=sf_escape($error)?></div><?php endif;?>
<nav class="document-tabs" aria-label="Belge yönetimi"><a class="<?=$tab==='list'?'active':''?>" href="<?=$base?>">Belgeler <span><?=$counts['all']?></span></a><a class="<?=$tab==='settings'?'active':''?>" href="<?=$base?>?tab=settings">Sayfa metinleri</a></nav>
<?php if($tab==='settings'):?>
<form method="post" action="<?=$base?>?tab=settings" class="panel document-panel"><input type="hidden" name="csrf" value="<?=sf_escape(sf_csrf())?>"><input type="hidden" name="action" value="save_settings"><input type="hidden" name="revision" value="<?=sf_escape(sf_content_digest($settings))?>"><h2>Belge merkezi metinleri</h2><p class="field-help">Sitenin ana dili İngilizcedir. Boş liste mesajı herhangi bir sertifika veya rapor varlığı iddia etmemelidir.</p><?php sf_doc_admin_input('title','Sayfa başlığı',$settings['title'],'text',180,true);?><div class="document-field"><label for="intro">Sayfa açıklaması</label><textarea name="intro" id="intro" rows="3" maxlength="1500" required><?=sf_escape($settings['intro'])?></textarea></div><?php sf_doc_admin_input('empty_title','Belge yokken gösterilen başlık',$settings['empty_title'],'text',180,true);?><div class="document-field"><label for="empty-text">Belge yokken gösterilen açıklama</label><textarea name="empty_text" id="empty-text" rows="3" maxlength="1500" required><?=sf_escape($settings['empty_text'])?></textarea></div><hr><h2>Sertifikalar sayfası</h2><p class="field-help">Sayfa adresi: <a href="/certificates/" target="_blank" rel="noopener">/certificates/</a>. Gerçek PDF dosyalarını belge türü “Sertifika” veya “Kaynak dokümanı” seçerek ekleyin.</p><?php sf_doc_admin_input('certificate_title','Sertifikalar sayfa başlığı',$settings['certificate_title'],'text',180,true);?><div class="document-field"><label for="certificate-intro">Sertifikalar sayfa açıklaması</label><textarea name="certificate_intro" id="certificate-intro" rows="3" maxlength="1500" required><?=sf_escape($settings['certificate_intro'])?></textarea></div><?php sf_doc_admin_input('certificate_empty_title','Sertifika yokken gösterilen başlık',$settings['certificate_empty_title'],'text',180,true);?><div class="document-field"><label for="certificate-empty-text">Sertifika yokken gösterilen açıklama</label><textarea name="certificate_empty_text" id="certificate-empty-text" rows="3" maxlength="1500" required><?=sf_escape($settings['certificate_empty_text'])?></textarea></div><button class="button" type="submit">Sayfa metinlerini kaydet</button></form>

<?php elseif($item):?>
<a class="document-back" href="<?=$base?>">← Belge listesine dön</a><form method="post" enctype="multipart/form-data" action="<?=$base.($isNew?'?new=1':'?edit='.rawurlencode($id))?>" class="document-editor"><input type="hidden" name="csrf" value="<?=sf_escape(sf_csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=sf_escape($item['id']??'')?>"><input type="hidden" name="revision" value="<?=sf_escape($item['updated_at']??'')?>">
<section class="panel document-panel"><h2><?=$isNew?'Yeni belge':'Belge bilgileri'?></h2><?php sf_doc_admin_input('title','Belge başlığı',$item['title'],'text',180,true);?><div class="document-field-grid"><div class="document-field"><label for="category">Belge türü</label><select name="category" id="category"><?php foreach($categoryLabels as $key=>$label):?><option value="<?=$key?>" <?=$item['category']===$key?'selected':''?>><?=sf_escape($label)?></option><?php endforeach;?></select></div><div class="document-field"><label for="language">Belge dili</label><select name="language" id="language"><?php foreach(sf_document_languages() as $key=>$label):?><option value="<?=sf_escape($key)?>" <?=$item['language']===$key?'selected':''?>><?=sf_escape($label)?></option><?php endforeach;?></select></div><?php sf_doc_admin_input('document_date','Belge tarihi',$item['document_date'],'date',10);sf_doc_admin_input('version','Sürüm / revizyon',$item['version'],'text',60);?></div><div class="document-field"><label for="description">Kısa açıklama</label><textarea name="description" id="description" rows="5" maxlength="1500"><?=sf_escape($item['description'])?></textarea><p class="field-help">Belgenin kapsamını açıklayın. Doğrulanmamış sertifika, performans veya yetkinlik iddiası eklemeyin.</p></div>
<div class="document-upload"><label for="pdf">PDF dosyası</label><input type="file" name="pdf" id="pdf" accept="application/pdf,.pdf"><p class="field-help">Geçerli PDF · en fazla 10 MB. Yeni dosya, kaydettiğinizde mevcut PDF’nin yerine geçer. Dosya yüklemeden taslak oluşturabilirsiniz.</p><?php if(!empty($item['file'])):?><a class="button button-ghost" href="<?=$base?>?download=<?=rawurlencode($item['id'])?>">Mevcut PDF’yi indir</a><p class="field-help"><?=number_format((int)$item['bytes']/1024,0,',','.')?> KB · Taslak dosyayı yalnızca giriş yapmış yönetici indirebilir.</p><?php endif;?></div></section>
<aside class="document-editor-side"><section class="panel document-panel"><h2>Yayın ve onay</h2><div class="document-field"><label for="status">Durum</label><select name="status" id="status"><option value="draft" <?=$item['status']!=='published'?'selected':''?>>Taslak — ziyaretçiye kapalı</option><option value="published" <?=$item['status']==='published'?'selected':''?>>Yayında — herkese açık</option></select></div><label class="document-check"><input type="checkbox" name="permission_approved" value="1" <?=$item['permission_approved']?'checked':''?>>Bu PDF’nin web sitesinde yayımlanması onaylandı.</label><div class="document-field"><label for="order">Sıralama</label><input type="number" name="order" id="order" min="0" max="999" value="<?=sf_escape($item['order'])?>" required><p class="field-help">Küçük sayı önce görünür.</p></div><div class="document-publication-note">Yayın için gerçek PDF ve yayın onayı gerekir. Taslaklar ve onaysız belgeler kamuya açık listede veya indirme adresinde gösterilmez.</div><button class="button button-full" type="submit">Belgeyi kaydet</button></section><section class="panel document-panel document-helper"><h3>Sayfaya özel broşürler</h3><p>Sayfanın üstündeki indirme düğmesine PDF bağlamak için mevcut Broşürler / PDF ekranını kullanın. Bu bölüm birden fazla kurumsal belgeyi listeler.</p><a href="/admin/brochures.php">Broşür yönetimini aç →</a></section></aside></form>
<?php if(!$isNew&&!empty($item['id'])):?><details class="panel document-delete"><summary>Belgeyi kalıcı olarak sil</summary><p>Kayıt ve PDF dosyası silinir. Sadece yayından kaldırmak için durumu Taslak yapabilirsiniz.</p><form method="post"><input type="hidden" name="csrf" value="<?=sf_escape(sf_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=sf_escape($item['id'])?>"><label class="document-check"><input type="checkbox" name="confirm_delete" value="1" required>Belgeyi ve PDF dosyasını kalıcı olarak silmek istiyorum.</label><button class="document-danger-button" type="submit">Belgeyi ve dosyasını sil</button></form></details><?php endif;?>

<?php else:?>
<div class="document-stat-grid"><div class="panel"><span>Toplam belge</span><strong><?=$counts['all']?></strong></div><div class="panel"><span>Yayında</span><strong><?=$counts['published']?></strong></div><div class="panel"><span>Taslak</span><strong><?=$counts['draft']?></strong></div></div><section class="panel document-panel"><nav class="document-filters" aria-label="Belge türü filtresi"><a class="<?=$filter===''?'active':''?>" href="<?=$base?>">Tümü</a><?php foreach($categoryLabels as $key=>$label):?><a class="<?=$filter===$key?'active':''?>" href="<?=$base?>?category=<?=$key?>"><?=sf_escape($label)?></a><?php endforeach;?></nav><div class="document-admin-list"><?php $visible=0;foreach($items as $entry):if($filter!==''&&$entry['category']!==$filter)continue;$visible++;?><a class="document-admin-row" href="<?=$base?>?edit=<?=rawurlencode($entry['id'])?>"><span class="document-file-icon">PDF</span><div class="document-row-copy"><strong><?=sf_escape($entry['title'])?></strong><span><?=sf_escape($categoryLabels[$entry['category']]??'Belge')?> · <?=sf_escape(sf_document_languages()[$entry['language']]??'')?><?=$entry['version']!==''?' · '.sf_escape($entry['version']):''?></span></div><span class="document-badge <?=$entry['status']==='published'?'published':'draft'?>"><?=$entry['status']==='published'?'Yayında':'Taslak'?></span><span class="document-row-open">Düzenle →</span></a><?php endforeach;?></div><?php if($visible===0):?><div class="document-admin-empty"><h3>Henüz belge eklenmedi.</h3><p>Onaylı PDF’leri kendi başlığı, tarihi ve sürümüyle ekleyin. Hazır olmayan belgeleri dosya yüklemeden taslak tutabilirsiniz.</p><a class="button button-ghost" href="<?=$base?>?new=1">İlk belgeyi ekle</a></div><?php endif;?></section>
<?php endif;?></main><footer class="admin-footer">SEAFORT <span>Belge merkezi</span><a href="/documents/" target="_blank" rel="noopener">Sayfayı görüntüle</a></footer></div></body></html>
